void __munlock_pagevec(struct pagevec *pvec, struct zone *zone) {
    int i;

    for (i = 0; i < pagevec_count(pvec); i++) {
        struct page *page = pvec->pages[i];

        if (PageLocked(page)) {
            unlock_page(page);
        }

        if (!PageLRU(page)) {
            continue;
        }

        if (!page->mapping) {
            __page_cache_release(page);
        }

        if (PageActive(page)) {
            zone->pages_scanned += 1;
        } else {
            pagevec_put_page(pvec, page, 1);
        }
    }

    pagevec_reinit(pvec);
}
